<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pg_basebackup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dbname=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;service=notes_source_replication&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
